public sealed class ProductService(IMemoryCache cache, CatalogDb db) {
    public Task<Product?> GetAsync(int id) =>
        cache.GetOrCreateAsync($"product:{id}", async e => {
            e.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
            e.SlidingExpiration = TimeSpan.FromMinutes(2);
            e.SetSize(1);              // cache must be configured with SizeLimit
            return await db.Products.FindAsync(id);
        });
}

