public sealed class Catalog(HybridCache cache) {
    public ValueTask<Product> GetAsync(int id, CancellationToken ct) =>
        cache.GetOrCreateAsync($"product:{id}", id,
            async (key, token) => await LoadAsync(id, token),
            new HybridCacheEntryOptions {
                Expiration = TimeSpan.FromMinutes(10),
                LocalCacheExpiration = TimeSpan.FromMinutes(2)
            },
            tags: ["catalog"], cancellationToken: ct);
}
